CREATE OR REPLACE FUNCTION public.get_current_staff_shift()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_shift public.staff_shifts%rowtype;
  v_name text;
begin
  if v_user is null or not private.is_staff() then
    raise exception 'Acceso no autorizado';
  end if;

  select full_name into v_name
  from public.staff_profiles
  where user_id=v_user;

  select * into v_shift
  from public.staff_shifts
  where user_id=v_user and closed_at is null
  order by opened_at desc
  limit 1;

  if not found then
    return jsonb_build_object('open',false,'employee_name',coalesce(v_name,''));
  end if;

  return jsonb_build_object(
    'open',true,'id',v_shift.id,
    'shift_number',v_shift.shift_code,
    'shift_code',v_shift.shift_code,
    'shift_date',v_shift.shift_date,
    'opened_at',v_shift.opened_at,
    'employee_name',coalesce(v_name,'')
  );
end
$function$

CREATE OR REPLACE FUNCTION public.backoffice_check_in(p_reservation_id uuid, p_spot_id uuid, p_actual_entry_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
declare
  r public.reservations%rowtype;
  s public.parking_sessions%rowtype;
  spot_type uuid;
begin
  if not private.is_staff() then raise exception 'Not authorized'; end if;

  select * into r
  from public.reservations
  where id = p_reservation_id
  for update;

  if not found then raise exception 'Reservation not found'; end if;
  if r.status = 'cancelled' then raise exception 'Reservation is cancelled'; end if;
  if p_actual_entry_at > r.exit_at then raise exception 'La estancia ya ha finalizado'; end if;
  if r.status not in ('confirmed','checked_in') then raise exception 'Reservation is not ready for check-in'; end if;

  if coalesce(trim(r.plate),'') = '' or coalesce(trim(r.vehicle_make_model),'') = '' then
    raise exception 'Completa matrícula y modelo antes de dar entrada';
  end if;

  select vehicle_type_id into spot_type
  from public.parking_spots
  where id=p_spot_id and active=true;

  if spot_type is null then raise exception 'Parking spot not found'; end if;
  if spot_type <> r.vehicle_type_id then raise exception 'Parking spot category does not match reservation'; end if;

  if exists(
    select 1
    from public.capacity_blocks b
    where b.spot_id = p_spot_id
      and b.active = true
      and b.starts_at <= p_actual_entry_at
      and b.ends_at > p_actual_entry_at
  ) then
    raise exception 'La plaza seleccionada está bloqueada';
  end if;

  -- A vehicle that has temporarily left keeps its assigned space reserved
  -- until its stay ends.
  if exists(
    select 1
    from public.reservations rr
    where rr.assigned_spot_id = p_spot_id
      and rr.id <> p_reservation_id
      and rr.exit_at > p_actual_entry_at
      and rr.status in ('confirmed','checked_in')
      and exists (
        select 1
        from public.parking_sessions ps
        where ps.reservation_id = rr.id
      )
  ) then
    raise exception 'La plaza está reservada por otra estancia vigente';
  end if;

  if exists(
    select 1
    from public.parking_sessions
    where spot_id=p_spot_id
      and status='inside'
      and reservation_id is distinct from p_reservation_id
  ) then
    raise exception 'Parking spot is occupied';
  end if;

  select * into s
  from public.parking_sessions
  where reservation_id=p_reservation_id
  order by created_at desc
  limit 1
  for update;

  if found then
    if s.status='inside' then raise exception 'Vehicle is already inside'; end if;

    update public.parking_sessions
    set spot_id=p_spot_id,
        plate=r.plate,
        vehicle_make_model=r.vehicle_make_model,
        customer_name=r.customer_name,
        customer_phone=r.customer_phone,
        actual_entry_at=coalesce(actual_entry_at,p_actual_entry_at),
        actual_exit_at=null,
        status='inside',
        updated_at=now()
    where id=s.id
    returning * into s;
  else
    insert into public.parking_sessions(
      reservation_id,vehicle_type_id,spot_id,plate,vehicle_make_model,
      customer_name,customer_phone,planned_entry_at,planned_exit_at,
      actual_entry_at,status,billing_mode,source,created_by
    )
    values(
      r.id,r.vehicle_type_id,p_spot_id,r.plate,r.vehicle_make_model,
      r.customer_name,r.customer_phone,r.entry_at,r.exit_at,
      p_actual_entry_at,'inside','reservation','reservation',auth.uid()
    )
    returning * into s;
  end if;

  update public.reservations
  set status='checked_in',
      assigned_spot_id=p_spot_id,
      updated_at=now()
  where id=r.id;

  insert into public.parking_events(
    session_id,event_type,event_at,new_spot_id,created_by
  )
  values(
    s.id,'check_in',p_actual_entry_at,p_spot_id,auth.uid()
  );

  return s.id;
end
$function$

CREATE OR REPLACE FUNCTION public.regularize_overstay_payment(p_reservation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_total numeric(10,2);
  v_due numeric(10,2);
  v_paid_before numeric(10,2);
  v_now timestamptz := clock_timestamp();
begin
  if v_user is null or not private.is_staff() then
    raise exception 'Acceso no autorizado';
  end if;

  select
    coalesce(overstay_total_eur,0),
    coalesce(overstay_due_eur,0)
  into v_total, v_due
  from public.reservation_backoffice
  where id = p_reservation_id;

  if not found then
    raise exception 'Reserva no encontrada';
  end if;

  select coalesce(overstay_paid_amount_eur,0)
  into v_paid_before
  from public.reservations
  where id=p_reservation_id
  for update;

  if v_due <= 0 then
    return jsonb_build_object(
      'ok', true,
      'amount_paid', 0,
      'paid_total', v_paid_before,
      'paid_at', v_now
    );
  end if;

  update public.reservations
  set overstay_paid_amount_eur = v_total,
      overstay_paid_at = v_now,
      updated_at = v_now
  where id = p_reservation_id;

  return jsonb_build_object(
    'ok', true,
    'amount_paid', v_due,
    'paid_total', v_total,
    'paid_at', v_now
  );
end
$function$

CREATE OR REPLACE FUNCTION public.require_open_staff_shift_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
begin
  if v_user is null then
    return coalesce(new,old);
  end if;

  if not private.is_staff() then
    return coalesce(new,old);
  end if;

  select role into v_role
  from public.staff_profiles
  where user_id=v_user and active=true;

  -- Administrator has unrestricted free access and never needs a shift.
  if v_role='admin' then
    return coalesce(new,old);
  end if;

  if not exists (
    select 1
    from public.staff_shifts
    where user_id=v_user
      and closed_at is null
  ) then
    raise exception 'Debes abrir turno antes de realizar operaciones';
  end if;

  return coalesce(new,old);
end
$function$

CREATE OR REPLACE FUNCTION public.close_staff_shift()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_shift public.staff_shifts%rowtype;
  v_now timestamptz := clock_timestamp();
  v_name text;
begin
  if v_user is null or not private.is_staff() then
    raise exception 'Acceso no autorizado';
  end if;

  select full_name into v_name
  from public.staff_profiles
  where user_id=v_user;

  select * into v_shift
  from public.staff_shifts
  where user_id=v_user and closed_at is null
  order by opened_at desc
  limit 1
  for update;

  if not found then
    raise exception 'No hay ningún turno abierto';
  end if;

  insert into public.staff_activity_log(shift_id,user_id,action,entity_type,entity_id,details)
  values(v_shift.id,v_user,'shift_closed','shift',v_shift.id,
    jsonb_build_object(
      'shift_number',v_shift.shift_code,
      'shift_code',v_shift.shift_code,
      'shift_date',v_shift.shift_date,
      'employee_name',coalesce(v_name,''),
      'closed_at',v_now
    ));

  update public.staff_shifts
  set closed_at=v_now
  where id=v_shift.id;

  return jsonb_build_object(
    'ok',true,'id',v_shift.id,
    'shift_number',v_shift.shift_code,
    'shift_code',v_shift.shift_code,
    'shift_date',v_shift.shift_date,
    'opened_at',v_shift.opened_at,
    'closed_at',v_now,
    'employee_name',coalesce(v_name,'')
  );
end
$function$

CREATE OR REPLACE FUNCTION public.open_staff_shift()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_shift public.staff_shifts%rowtype;
  v_local timestamp := clock_timestamp() at time zone 'Europe/Madrid';
  v_hour integer;
  v_code smallint;
  v_date date;
  v_name text;
  v_role text;
begin
  if v_user is null or not private.is_staff() then
    raise exception 'Acceso no autorizado';
  end if;

  select full_name, role into v_name, v_role
  from public.staff_profiles
  where user_id=v_user and active=true;

  if v_name is null then
    raise exception 'Usuario no autorizado';
  end if;

  if v_role='admin' then
    raise exception 'El administrador utiliza acceso libre y no participa en turnos';
  end if;

  select * into v_shift
  from public.staff_shifts
  where user_id=v_user and closed_at is null
  order by opened_at desc
  limit 1;

  if found then
    return jsonb_build_object(
      'ok',true,'already_open',true,'id',v_shift.id,
      'shift_number',v_shift.shift_code,
      'shift_code',v_shift.shift_code,
      'shift_date',v_shift.shift_date,
      'opened_at',v_shift.opened_at,
      'employee_name',v_name
    );
  end if;

  v_hour := extract(hour from v_local);
  if v_hour >= 22 then
    v_code := 1;
    v_date := v_local::date + 1;
  elsif v_hour < 6 then
    v_code := 1;
    v_date := v_local::date;
  elsif v_hour < 14 then
    v_code := 2;
    v_date := v_local::date;
  else
    v_code := 3;
    v_date := v_local::date;
  end if;

  insert into public.staff_shifts(user_id,shift_code,shift_date)
  values(v_user,v_code,v_date)
  returning * into v_shift;

  insert into public.staff_activity_log(shift_id,user_id,action,entity_type,entity_id,details)
  values(v_shift.id,v_user,'shift_opened','shift',v_shift.id,
    jsonb_build_object(
      'shift_number',v_code,
      'shift_code',v_code,
      'shift_date',v_date,
      'employee_name',v_name
    ));

  return jsonb_build_object(
    'ok',true,'already_open',false,'id',v_shift.id,
    'shift_number',v_code,
    'shift_code',v_code,
    'shift_date',v_date,
    'opened_at',v_shift.opened_at,
    'employee_name',v_name
  );
end
$function$

CREATE OR REPLACE FUNCTION public.rotation_check_out(p_session_id uuid, p_discount_bono_eur numeric DEFAULT 0, p_payment_method text DEFAULT 'cash'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_ctx jsonb;
  v_session public.rotation_sessions%rowtype;
  v_tariff public.rotation_tariffs%rowtype;
  v_calc jsonb;
  v_exit timestamptz := clock_timestamp();
  v_base numeric(10,2);
  v_discount numeric(10,2);
  v_total numeric(10,2);
  v_method text := lower(trim(coalesce(p_payment_method,'')));
begin
  v_ctx := public.rotation_operator_context();

  if v_method not in ('cash','card') then
    raise exception 'Forma de pago no válida';
  end if;

  select *
  into v_session
  from public.rotation_sessions
  where id=p_session_id
  for update;

  if not found or v_session.status <> 'inside' then
    raise exception 'El vehículo no consta actualmente dentro';
  end if;

  select *
  into v_tariff
  from public.rotation_tariffs
  where id=v_session.tariff_id;

  if not v_tariff.calculation_ready then
    raise exception 'Los tramos de % todavía no están configurados', v_tariff.name;
  end if;

  v_calc := public.calculate_rotation_amount(
    v_tariff.code,
    v_session.entry_at,
    v_exit
  );

  v_base := round((v_calc->>'amount_eur')::numeric,2);
  v_discount := round(greatest(coalesce(p_discount_bono_eur,0),0),2);

  if v_discount > v_base then
    v_discount := v_base;
  end if;

  v_total := round(greatest(v_base-v_discount,0),2);

  update public.rotation_sessions
  set exit_at=v_exit,
      status='departed',
      raw_amount_eur=(v_calc->>'raw_amount_eur')::numeric,
      tariff_amount_eur=v_base,
      discount_bono_eur=v_discount,
      amount_eur=v_total,
      payment_method=v_method,
      paid_at=v_exit,
      exit_user_id=(v_ctx->>'user_id')::uuid,
      exit_employee_name=v_ctx->>'employee_name',
      exit_shift_id=nullif(v_ctx->>'shift_id','')::uuid,
      exit_shift_code=nullif(v_ctx->>'shift_code','')::smallint,
      exit_shift_date=(v_ctx->>'shift_date')::date,
      updated_at=v_exit
  where id=v_session.id;

  if v_session.source_reservation_id is not null then
    update public.reservations
    set status='completed',
        rotation_pending=false,
        assigned_spot_id=null,
        updated_at=v_exit
    where id=v_session.source_reservation_id;
  end if;

  return v_calc || jsonb_build_object(
    'ok',true,
    'id',v_session.id,
    'ticket_number',v_session.ticket_number,
    'plate',v_session.plate,
    'entry_at',v_session.entry_at,
    'exit_at',v_exit,
    'tariff_amount_eur',v_base,
    'discount_bono_eur',v_discount,
    'amount_eur',v_total,
    'payment_method',v_method,
    'employee_name',v_ctx->>'employee_name',
    'shift_code',v_ctx->>'shift_code',
    'shift_date',v_ctx->>'shift_date',
    'access_mode',v_ctx->>'access_mode',
    'source_reservation_id',v_session.source_reservation_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.rotation_check_in(p_tariff_code text, p_plate text, p_client_text text DEFAULT NULL::text, p_authorized_text text DEFAULT NULL::text, p_leaves_keys boolean DEFAULT false, p_key_number text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_ctx jsonb;
  v_tariff public.rotation_tariffs%rowtype;
  v_session public.rotation_sessions%rowtype;
  v_inside integer;
  v_plate text := upper(trim(coalesce(p_plate,'')));
begin
  v_ctx := public.rotation_operator_context();

  if length(v_plate) < 3 then
    raise exception 'Introduce una matrícula válida';
  end if;

  select *
  into v_tariff
  from public.rotation_tariffs
  where code=upper(trim(p_tariff_code))
    and active=true;

  if not found then
    raise exception 'Tarifa de Rotación no encontrada';
  end if;

  if v_tariff.capacity <= 0 then
    raise exception 'Esta tarifa no tiene plazas configuradas';
  end if;

  if exists(
    select 1
    from public.rotation_sessions
    where upper(plate)=v_plate
      and status='inside'
  ) then
    raise exception 'Este vehículo ya consta dentro de Rotación';
  end if;

  select count(*)
  into v_inside
  from public.rotation_sessions
  where tariff_id=v_tariff.id
    and status='inside'
    and billing_only=false;

  if v_inside >= v_tariff.capacity then
    raise exception 'No quedan plazas libres para %',v_tariff.name;
  end if;

  insert into public.rotation_sessions(
    tariff_id,plate,client_text,authorized_text,leaves_keys,key_number,
    entry_user_id,entry_employee_name,entry_shift_id,entry_shift_code,
    entry_shift_date,billing_only
  )
  values(
    v_tariff.id,v_plate,
    nullif(trim(coalesce(p_client_text,'')),''),
    nullif(trim(coalesce(p_authorized_text,'')),''),
    coalesce(p_leaves_keys,false),
    case
      when coalesce(p_leaves_keys,false)
        then nullif(trim(coalesce(p_key_number,'')),'')
      else null
    end,
    (v_ctx->>'user_id')::uuid,
    v_ctx->>'employee_name',
    nullif(v_ctx->>'shift_id','')::uuid,
    nullif(v_ctx->>'shift_code','')::smallint,
    (v_ctx->>'shift_date')::date,
    false
  )
  returning *
  into v_session;

  return jsonb_build_object(
    'ok',true,
    'id',v_session.id,
    'ticket_number',v_session.ticket_number,
    'plate',v_session.plate,
    'entry_at',v_session.entry_at,
    'tariff_code',v_tariff.code,
    'tariff_name',v_tariff.name,
    'capacity',v_tariff.capacity,
    'occupied_after',v_inside+1,
    'employee_name',v_ctx->>'employee_name',
    'shift_code',v_ctx->>'shift_code',
    'shift_date',v_ctx->>'shift_date',
    'access_mode',v_ctx->>'access_mode'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.mark_monthly_subscription_paid(p_subscriber_id uuid, p_billing_month date, p_payment_method text)
 RETURNS monthly_subscription_payments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_result public.monthly_subscription_payments; v_role text;
begin
 select role into v_role from public.staff_profiles where user_id=auth.uid() and active;
 if v_role is null then raise exception 'No autorizado'; end if;
 if p_payment_method not in ('bank','card','cash') then raise exception 'Forma de pago no válida'; end if;
 if extract(day from p_billing_month)<>1 then raise exception 'Mes no válido'; end if;
 if p_billing_month > date_trunc('month',current_date + interval '1 month')::date or
    (p_billing_month=date_trunc('month',current_date + interval '1 month')::date and extract(day from current_date)<25)
 then raise exception 'El mes siguiente solo puede abonarse desde el día 25';end if;
 if not exists(select 1 from public.monthly_subscribers where id=p_subscriber_id and active) then raise exception 'Abonado no activo';end if;
 insert into public.monthly_subscription_payments(subscriber_id,billing_month,payment_method,paid_by)
 values(p_subscriber_id,p_billing_month,p_payment_method,auth.uid())
 on conflict(subscriber_id,billing_month) do update set payment_method=excluded.payment_method
 returning * into v_result;
 return v_result;
end;$function$

CREATE OR REPLACE FUNCTION public.issue_parking_invoice(p_entity_type text, p_entity_id uuid, p_billing_month date DEFAULT NULL::date, p_customer_tax_id text DEFAULT NULL::text, p_customer_address text DEFAULT NULL::text)
 RETURNS parking_invoices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.parking_invoices; s public.monthly_subscribers; r public.reservations; v_price numeric; v_discount numeric; v_vat numeric; v_total numeric;
begin
 if not exists(select 1 from public.staff_profiles where user_id=auth.uid() and active=true and role in ('admin','manager')) then raise exception 'Solo administradores y gerentes pueden emitir facturas';end if;
 if p_entity_type='subscriber' then
  select * into s from public.monthly_subscribers where id=p_entity_id;
  if not found then raise exception 'Abonado inexistente';end if;
  if p_billing_month is null then raise exception 'Indica mes de facturación';end if;
  v_price:=s.price_eur; v_discount:=coalesce(s.discount_amount_eur,round(s.price_eur*s.discount_pct/100,2));
  v_vat:=round((v_price-v_discount)*s.vat_pct/100,2);v_total:=v_price-v_discount+v_vat;
  insert into public.parking_invoices(entity_type,entity_id,billing_month,customer_name,customer_tax_id,customer_address,vehicle,plate,amount_before_vat,discount_eur,vat_eur,total_eur)
  values('subscriber',p_entity_id,p_billing_month,s.customer_name,coalesce(nullif(p_customer_tax_id,''),s.tax_id),coalesce(nullif(p_customer_address,''),concat_ws(' ',s.address,s.postal_code,s.city)),s.vehicle,s.plate,v_price,v_discount,v_vat,v_total)
  on conflict(entity_type,entity_id,billing_month) do nothing;
 elsif p_entity_type='reservation' then
  select * into r from public.reservations where id=p_entity_id;
  if not found then raise exception 'Estancia inexistente';end if;
  v_total:=r.amount_eur;v_price:=round(v_total/1.21,2);v_discount:=0;v_vat:=v_total-v_price;
  insert into public.parking_invoices(entity_type,entity_id,billing_month,customer_name,customer_tax_id,customer_address,vehicle,plate,amount_before_vat,discount_eur,vat_eur,total_eur)
  values('reservation',p_entity_id,null,coalesce(r.customer_name,'Cliente sin identificar'),nullif(p_customer_tax_id,''),nullif(p_customer_address,''),r.vehicle_make_model,r.plate,v_price,v_discount,v_vat,v_total)
  on conflict do nothing;
 else raise exception 'Tipo de factura no válido';end if;
 select * into v from public.parking_invoices where entity_type=p_entity_type and entity_id=p_entity_id and billing_month is not distinct from p_billing_month order by issued_at desc limit 1;
 return v;
end;$function$

