CREATE OR REPLACE FUNCTION public.rotation_operator_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_name text;
  v_role text;
  v_shift public.staff_shifts%rowtype;
  v_date date := (clock_timestamp() at time zone 'Europe/Madrid')::date;
begin
  if v_user is null or not private.is_staff() then
    raise exception 'Acceso no autorizado';
  end if;

  select full_name,role into v_name,v_role
  from public.staff_profiles
  where user_id=v_user and active=true;

  if v_name is null then raise exception 'Usuario no autorizado'; end if;

  select * into v_shift
  from public.staff_shifts
  where user_id=v_user and closed_at is null
  order by opened_at desc
  limit 1;

  if not found and v_role <> 'admin' then
    raise exception 'Debes realizar un turno para operar en Rotación';
  end if;

  return jsonb_build_object(
    'user_id',v_user,
    'employee_name',v_name,
    'role',v_role,
    'shift_id',case when found then v_shift.id else null end,
    'shift_code',case when found then v_shift.shift_code else null end,
    'shift_date',case when found then v_shift.shift_date else v_date end,
    'access_mode',case when found then 'shift' else 'admin_free' end
  );
end
$function$

