CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_reservation_computed_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_price numeric(10,2);
begin
  if new.duration_days < 1 or new.duration_days > 24 then
    raise exception 'La duración debe estar entre 1 y 24 días';
  end if;

  new.exit_at := new.entry_at + (new.duration_days::double precision * interval '24 hours');
  new.plate := case when new.plate is null then null else upper(trim(new.plate)) end;

  select t.price_eur into v_price
  from public.tariffs t
  where t.vehicle_type_id = new.vehicle_type_id
    and t.days = new.duration_days;

  if v_price is null then
    raise exception 'No existe tarifa para este tipo de vehículo y duración';
  end if;

  new.tariff_amount_eur := v_price;

  if new.payment_method = 'hotel_voucher' and not new.manual_price_override then
    new.amount_eur := 0;
  elsif not new.manual_price_override then
    new.amount_eur := v_price;
  end if;

  if new.status = 'pending_payment' and new.expires_at is null then
    new.expires_at := now() + interval '20 minutes';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_overbooking()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_available integer;
  v_consumes_capacity boolean;
begin
  v_consumes_capacity := new.status in ('confirmed','checked_in')
    or (new.status = 'pending_payment' and coalesce(new.expires_at, now() + interval '1 second') > now());
  if not v_consumes_capacity then return new; end if;
  perform pg_advisory_xact_lock(hashtext(new.vehicle_type_id::text)::bigint);
  select private.get_available_spaces(
    new.vehicle_type_id,
    new.entry_at,
    new.exit_at,
    case when tg_op = 'UPDATE' then old.id else null end
  ) into v_available;
  if coalesce(v_available, 0) < 1 then
    raise exception 'No hay plazas disponibles para todo el intervalo solicitado';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.log_staff_activity_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_shift uuid;
  v_action text;
  v_id uuid;
  v_details jsonb := '{}'::jsonb;
begin
  if v_user is null or not private.is_staff() then
    return coalesce(new,old);
  end if;

  select id into v_shift
  from public.staff_shifts
  where user_id=v_user and closed_at is null
  order by opened_at desc
  limit 1;

  if v_shift is null then
    return coalesce(new,old);
  end if;

  if tg_table_name='reservations' then
    v_id := coalesce(new.id,old.id);
    v_action := case when tg_op='INSERT' then 'reservation_created' else 'reservation_updated' end;
    v_details := jsonb_build_object(
      'reference',coalesce(new.reference,old.reference),
      'plate',coalesce(new.plate,old.plate),
      'status',coalesce(new.status,old.status),
      'amount_eur',coalesce(new.amount_eur,old.amount_eur)
    );
  elsif tg_table_name='parking_events' then
    v_id := coalesce(new.id,old.id);
    v_action := 'parking_'||coalesce(new.event_type,old.event_type);
    v_details := jsonb_build_object(
      'session_id',coalesce(new.session_id,old.session_id),
      'event_at',coalesce(new.event_at,old.event_at)
    );
  elsif tg_table_name='capacity_blocks' then
    v_id := coalesce(new.id,old.id);
    v_action := case
      when tg_op='INSERT' then 'spot_block_created'
      when coalesce(new.active,false)=false and coalesce(old.active,false)=true then 'spot_block_removed'
      else 'spot_block_updated'
    end;
    v_details := jsonb_build_object(
      'spot_id',coalesce(new.spot_id,old.spot_id),
      'blocked_spaces',coalesce(new.blocked_spaces,old.blocked_spaces)
    );
  else
    return coalesce(new,old);
  end if;

  insert into public.staff_activity_log(shift_id,user_id,action,entity_type,entity_id,details)
  values(v_shift,v_user,v_action,tg_table_name,v_id,v_details);

  return coalesce(new,old);
end
$function$

CREATE OR REPLACE FUNCTION public.require_open_staff_shift_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
begin
  if v_user is null then
    return coalesce(new,old);
  end if;

  if not private.is_staff() then
    return coalesce(new,old);
  end if;

  select role into v_role
  from public.staff_profiles
  where user_id=v_user and active=true;

  -- Administrator has unrestricted free access and never needs a shift.
  if v_role='admin' then
    return coalesce(new,old);
  end if;

  if not exists (
    select 1
    from public.staff_shifts
    where user_id=v_user
      and closed_at is null
  ) then
    raise exception 'Debes abrir turno antes de realizar operaciones';
  end if;

  return coalesce(new,old);
end
$function$

CREATE OR REPLACE FUNCTION public.assign_web_reservation_spot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_spot uuid;
begin
 if new.source <> 'web' then return new; end if;
 if new.status not in ('pending_payment','confirmed','checked_in') then return new; end if;
 if new.assigned_spot_id is not null then return new; end if;
 perform pg_advisory_xact_lock(hashtext(new.vehicle_type_id::text)::bigint);
 select p.id into v_spot from public.parking_spots p
 where p.active and p.vehicle_type_id=new.vehicle_type_id
 and not exists(select 1 from public.capacity_blocks b where b.active and b.spot_id=p.id and b.starts_at<new.exit_at and b.ends_at>new.entry_at)
 and not exists(select 1 from public.reservations r where r.assigned_spot_id=p.id and r.id is distinct from new.id and r.status in ('confirmed','checked_in','pending_payment') and (r.status<>'pending_payment' or coalesce(r.expires_at,now()+interval '1 second')>now()) and r.entry_at<new.exit_at and r.exit_at>new.entry_at)
 and not exists(select 1 from public.parking_sessions ps where ps.spot_id=p.id and ps.status='inside' and (ps.planned_exit_at is null or ps.planned_exit_at>new.entry_at))
 order by random() limit 1;
 if v_spot is null then raise exception 'No hay una plaza libre para asignar durante las fechas solicitadas'; end if;
 new.assigned_spot_id:=v_spot;
 return new;
end;$function$

