CREATE OR REPLACE FUNCTION public.calculate_rotation_amount(p_tariff_code text, p_entry_at timestamp with time zone, p_exit_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_tariff public.rotation_tariffs%rowtype;
  v_total_minutes integer;
  v_full_days integer;
  v_remainder integer;
  v_chargeable_remainder integer;
  v_partial_raw numeric(14,5) := 0;
  v_raw numeric(14,5);
  v_rounded numeric(10,2);
begin
  if auth.uid() is null or not private.is_staff() then
    raise exception 'Acceso no autorizado';
  end if;

  if p_exit_at < p_entry_at then
    raise exception 'La salida no puede ser anterior a la entrada';
  end if;

  select * into v_tariff
  from public.rotation_tariffs
  where code=upper(trim(p_tariff_code))
    and active=true;

  if not found then
    raise exception 'Tarifa de rotación no encontrada';
  end if;

  if not v_tariff.calculation_ready then
    raise exception 'Los tramos de esta tarifa todavía no están configurados';
  end if;

  v_total_minutes := greatest(0,floor(extract(epoch from (p_exit_at-p_entry_at))/60.0)::integer);
  v_full_days := v_total_minutes / 1440;
  v_remainder := v_total_minutes % 1440;

  if v_remainder >= 720 then
    v_chargeable_remainder := 720;
    v_partial_raw := v_tariff.daily_cap_eur;
  else
    v_chargeable_remainder := v_remainder;

    select coalesce(sum(
      greatest(0,least(v_chargeable_remainder,s.to_minute)-s.from_minute)::numeric
      * s.price_per_minute_eur
    ),0)
    into v_partial_raw
    from public.rotation_tariff_segments s
    where s.tariff_id=v_tariff.id
      and s.from_minute < v_chargeable_remainder;
  end if;

  v_raw := (v_full_days * v_tariff.daily_cap_eur) + v_partial_raw;
  v_rounded := public.floor_to_rotation_step(v_raw,v_tariff.rounding_step_eur);

  return jsonb_build_object(
    'tariff_code',v_tariff.code,
    'tariff_name',v_tariff.name,
    'total_minutes',v_total_minutes,
    'full_days',v_full_days,
    'remainder_minutes',v_remainder,
    'chargeable_remainder_minutes',v_chargeable_remainder,
    'daily_cap_eur',v_tariff.daily_cap_eur,
    'raw_amount_eur',round(v_raw,5),
    'amount_eur',round(v_rounded,2),
    'rounding_step_eur',v_tariff.rounding_step_eur
  );
end
$function$

CREATE OR REPLACE FUNCTION public.record_parking_movement(p_reservation_id uuid, p_direction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_user uuid := auth.uid();
  v_res public.reservations%rowtype;
  v_session public.parking_sessions%rowtype;
  v_last_event text;
  v_direction text := upper(trim(coalesce(p_direction,'')));
begin
  if v_user is null or not private.is_staff() then
    raise exception 'Acceso no autorizado';
  end if;

  if v_direction not in ('IN','OUT') then
    raise exception 'Movimiento no válido';
  end if;

  select * into v_res
  from public.reservations
  where id = p_reservation_id
  for update;

  if not found then
    raise exception 'Reserva no encontrada';
  end if;

  if v_res.status = 'cancelled' then
    raise exception 'La reserva está cancelada';
  end if;

  if v_direction='IN' and v_now > v_res.exit_at then
    raise exception 'La estancia ya ha finalizado';
  end if;

  select * into v_session
  from public.parking_sessions
  where reservation_id = p_reservation_id
  order by created_at desc
  limit 1
  for update;

  if not found then
    if v_direction = 'OUT' then
      raise exception 'El vehículo ya está fuera';
    end if;

    insert into public.parking_sessions(
      reservation_id, vehicle_type_id, spot_id, plate, vehicle_make_model,
      customer_name, customer_phone, planned_entry_at, planned_exit_at,
      status, billing_mode, source, created_by
    )
    values(
      v_res.id, v_res.vehicle_type_id, v_res.assigned_spot_id, v_res.plate, v_res.vehicle_make_model,
      v_res.customer_name, v_res.customer_phone, v_res.entry_at, v_res.exit_at,
      'expected', 'reservation', 'reservation', v_user
    )
    returning * into v_session;
  end if;

  select e.event_type into v_last_event
  from public.parking_events e
  where e.session_id = v_session.id
    and e.event_type in ('check_in','check_out')
  order by e.event_at desc, e.id desc
  limit 1;

  if v_direction = 'IN' then
    if v_last_event = 'check_in' or v_session.status = 'inside' then
      raise exception 'El vehículo ya está dentro';
    end if;

    insert into public.parking_events(session_id,event_type,event_at,new_spot_id,created_by)
    values(v_session.id,'check_in',v_now,v_session.spot_id,v_user);

    update public.parking_sessions
      set status='inside',
          actual_entry_at=coalesce(actual_entry_at,v_now),
          actual_exit_at=null,
          updated_at=v_now
    where id=v_session.id;

    update public.reservations
      set status='checked_in', updated_at=v_now
    where id=v_res.id;
  else
    if coalesce(v_last_event,'') <> 'check_in' and v_session.status <> 'inside' then
      raise exception 'El vehículo ya está fuera';
    end if;

    insert into public.parking_events(session_id,event_type,event_at,old_spot_id,created_by)
    values(v_session.id,'check_out',v_now,v_session.spot_id,v_user);

    update public.parking_sessions
      set status='departed',
          actual_exit_at=v_now,
          updated_at=v_now
    where id=v_session.id;

    update public.reservations
      set status=case
          when v_now < v_res.exit_at then 'confirmed'
          else 'completed'
        end,
        updated_at=v_now
    where id=v_res.id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'reservation_id', v_res.id,
    'direction', v_direction,
    'event_at', v_now
  );
end
$function$

CREATE OR REPLACE FUNCTION public.register_staff_document(p_document_type text, p_entity_type text, p_entity_id uuid, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_shift public.staff_shifts%rowtype;
  v_name text;
  v_role text;
  v_id bigint;
  v_issued timestamptz := clock_timestamp();
  v_shift_date date := (clock_timestamp() at time zone 'Europe/Madrid')::date;
begin
  if v_user is null or not private.is_staff() then
    raise exception 'Acceso no autorizado';
  end if;

  select full_name,role into v_name,v_role
  from public.staff_profiles
  where user_id=v_user and active=true;

  select * into v_shift
  from public.staff_shifts
  where user_id=v_user and closed_at is null
  order by opened_at desc
  limit 1;

  if not found and v_role <> 'admin' then
    raise exception 'Debes abrir turno antes de emitir documentos';
  end if;

  insert into public.issued_documents(
    document_type,entity_type,entity_id,shift_id,user_id,employee_name,
    shift_code,shift_date,details,issued_at
  )
  values(
    p_document_type,p_entity_type,p_entity_id,
    case when found then v_shift.id else null end,
    v_user,coalesce(v_name,''),
    case when found then v_shift.shift_code else null end,
    case when found then v_shift.shift_date else v_shift_date end,
    coalesce(p_details,'{}'::jsonb) ||
      case when found then '{}'::jsonb else jsonb_build_object('access_mode','admin_free') end,
    v_issued
  )
  returning id into v_id;

  if found then
    insert into public.staff_activity_log(shift_id,user_id,action,entity_type,entity_id,details)
    values(
      v_shift.id,v_user,'document_issued',p_entity_type,p_entity_id,
      jsonb_build_object(
        'document_id',v_id,
        'document_type',p_document_type,
        'shift_code',v_shift.shift_code,
        'shift_date',v_shift.shift_date,
        'employee_name',coalesce(v_name,'')
      ) || coalesce(p_details,'{}'::jsonb)
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'document_id',v_id,
    'employee_name',coalesce(v_name,''),
    'shift_number',case when found then v_shift.shift_code else null end,
    'shift_code',case when found then v_shift.shift_code else null end,
    'shift_date',case when found then v_shift.shift_date else v_shift_date end,
    'access_mode',case when found then 'shift' else 'admin_free' end,
    'issued_at',v_issued
  );
end
$function$
